    chart('product-chart', { type: key === 'purview' ? 'bar' : 'line', data: { labels, datasets: [{ label: key === 'intune' ? 'Compliant devices (%)' : key === 'entra' ? 'Sign-in attempts' : 'DLP policy matches', data: values, backgroundColor: key === 'purview' ? '#3d9ba4' : '#4386d215', borderColor: data.products[key].color, borderWidth: 2, fill: true, tension: .3, pointRadius: 3, borderRadius: 3, maxBarThickness: 30 }] }, options: { scales: key === 'intune' ? { ...chartAxes(), y: { ...chartAxes().y, min: 90, max: 100 } } : chartAxes(), plugins: { legend: { display: false } } } });
