    const productTitle = product ? sectionLabel || (state.tab === 'overview' ? homeNames[state.view] : state.tab === 'controls' ? state.view === 'entra' ? 'Conditional Access' : state.view === 'purview' ? 'Data Loss Prevention' : 'Policies' : state.tab === 'inventory' ? state.view === 'entra' ? 'Users' : state.view === 'purview' ? 'Data classification' : 'Devices' : 'Capabilities & licensing') : null;
    const title = product ? [productTitle, product.tagline, ''] : titles[state.view] || titles.overview;
