      home.querySelectorAll('.spotlight-grid button').forEach((button,index)=>{button.dataset.portalTarget=['section:update-rings','section:autopilot'][index];});
      home.querySelectorAll('.intune-resource-grid [data-portal-target]').forEach((button,index)=>{button.dataset.portalTarget=['section:endpoint-security','section:app-protection','section:reports'][index];});
